#!/usr/bin/env bash
# Generated by scripts/build-deploy.sh — do not edit directly.
# setup-cursor-mcp.sh — Installs/updates MCP servers for Cursor on macOS/Linux
# Safe to re-run — replaces ~/.cursor/mcp.json with latest config.
#
# Cursor uses its own MCP config at ~/.cursor/mcp.json (separate from Claude Code's ~/.claude.json).
# Remote servers use the "url" key directly. Local stdio servers use "command" + "args".

set -euo pipefail

# Check that Node.js is available (required for Chrome DevTools MCP)
if ! command -v node &> /dev/null; then
    echo "Node.js not found. Installing via Homebrew (required for Chrome DevTools MCP)..."
    if ! command -v brew &> /dev/null; then
        echo "Error: Homebrew not found. Install Node.js manually: https://nodejs.org"
        exit 1
    fi
    brew install node@22
    echo "Node.js installed."
else
    echo "Node.js $(node --version) found."
fi

# Ensure ~/.cursor directory exists
cursor_dir="$HOME/.cursor"
mkdir -p "$cursor_dir"

mcp_json="$cursor_dir/mcp.json"

if [ -f "$mcp_json" ]; then
    echo "Replacing existing $mcp_json"
else
    echo "Creating $mcp_json"
fi

# Write the config (macOS uses npx directly, no cmd /c wrapper)
cat > "$mcp_json" << 'EOF'
{
  "mcpServers": {
    "chrome-devtools": {
      "command": "npx",
      "args": ["-y", "chrome-devtools-mcp@latest"]
    },
    "vercel": {
      "url": "https://mcp.vercel.com"
    },
    "webflow": {
      "url": "https://mcp.webflow.com/mcp"
    }
  }
}
EOF

echo ""
echo "Cursor MCP config written to $mcp_json"
echo ""
echo "Servers configured:"
echo "  - chrome-devtools (stdio via npx)"
echo "  - vercel (remote HTTP)"
echo "  - webflow (remote HTTP)"
echo ""
echo "Next steps:"
echo "  1. Restart Cursor"
echo "  2. Go to Cursor Settings > Tools & MCP to see the servers"
echo "  3. Authenticate Vercel and Webflow from the Tools & MCP settings page"
